const errors = [];
let page;
let reattached = 0;
/**
 * The app's WebView page. If Android restarts the WebView's renderer (or the
 * debugging connection drops), wait for the new one and carry on — and say so.
 */
async function app() {
  if (page && !page.isClosed()) return page;
  if (page) {
    reattached++;
    console.log('    (the WebView went away; waiting for its replacement)');
    await new Promise((done) => setTimeout(done, 3000));
  }
  for (let i = 0; i < 3; i++) {
    const webview = await device.webView({ pkg: PKG }, { timeout: 60_000 });
    page = await webview.page();
    if (!page.isClosed()) break;
    await new Promise((done) => setTimeout(done, 3000));
  }
  page.on('pageerror', (e) => errors.push(e.message));
  page.on('crash', () => console.log('    (the WebView renderer crashed)'));
  return page;
}
await app();
